// Run against the game/ directory generated by this comparison's build.cjs.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root=process.env.MOBILITY_GAME;
if(!root)throw Error('Set MOBILITY_GAME to the game directory of the pinned V7 distribution');
const at = name => path.resolve(root, name);
const importNative = name => import(pathToFileURL(at(name)));

const fixture = JSON.parse(fs.readFileSync(new URL('../home-mobility-v7/geometry-fixture.json', import.meta.url)));
const { selectRecoveredScene } = await importNative('home-production-manifest.mjs');
const { createRecoveredNavigation } = await importNative('home-recovered-navigation-finish.mjs');
const { extendVisibleGroundNavigation } = await importNative('home-visible-ground-navigation-finish.mjs');
const { insidePolygon } = await importNative('home-art-navigation-finish.mjs');
const { residents, nativeStage, stageToCss, cover } = fixture;
const sx = stageToCss.scaleX, sy = stageToCss.scaleY;
export const spec = selectRecoveredScene('forest');
const legacy = createRecoveredNavigation(spec, nativeStage, nativeStage, { stableGrid: true });
const navigation = extendVisibleGroundNavigation(legacy, {
  spec, cover, stage: { left: stageToCss.left / sx, top: stageToCss.top / sy },
  presentation: { x: 0, y: 0, scaleX: sx, scaleY: sy },
});
const polygons = spec.foreground.map(poly => poly.map(([u, v]) => [
  (cover.left + u * cover.width - stageToCss.left) / sx,
  (cover.top + v * cover.height - stageToCss.top) / sy,
]));
const byKey = new Map(residents.map(r => [r.key, r]));
const people = residents.map(({ key, x, y, w, h }) => ({ key, kind: key.split(':')[0], x, y, w, h }));

function mask(resident, p) {
  for (const dx of [-.3 * resident.w, 0, .3 * resident.w]) {
    for (const dy of [.22 * resident.h, .5 * resident.h, .8 * resident.h]) {
      if (polygons.some(poly => insidePolygon(p.x + dx, p.y - dy, poly))) return false;
    }
  }
  return true;
}

export const testedKeys=['tanuki','hamster','otter','panda','sekizou','many_tail_fox','box'].map(k=>'companion:'+k);
const agedRows=JSON.parse(fs.readFileSync(new URL('./forest-footprint-fixture.json',import.meta.url))).residents;
export const nativeSource=fs.readFileSync(at('home-production-model-mobility-v7.js'),'utf8');
export function forest(api,mode='aged',seed=214){
 const positions=new Map(mode==='aged'?agedRows.map(([key,x,y])=>[key,{x,y}]):people.map(r=>[r.key,r]));
 const initial=people.map(r=>({...r,...positions.get(r.key)}));
 let placing=true;
 const scene={
   width:nativeStage.width,height:nativeStage.height,groundTop:24,region:'forest',time:'day',weather:'sunny',
   navigation:{...navigation,initialPoint:i=>initial[i]},
   referenceBounds:actor=>api.bounds(actor,{...scene,actorBounds:null}),
   actorBounds:actor=>byKey.get(actor.key).bounds,
   planVisibility:actor=>p=>mask(actor,p),
   visible(p,a){return placing?Math.hypot(p.x-positions.get(a.key).x,p.y-positions.get(a.key).y)<1e-7:mask(a,p);}
 };
 const model=api.createModel({random:()=>((seed=Math.imul(16807,seed)>>>0)/4294967296)});
 model.sync(initial,scene);placing=false;
 assert.deepEqual(model.snapshot().map(a=>[a.key,a.x,a.y]),initial.map(a=>[a.key,a.x,a.y]));
 return {model,scene,rows:initial,sx,sy};
}
